public interface IPaymentGateway
{
    Task<string> ChargeAsync(decimal amount, CancellationToken cancellationToken);
}

public sealed class Checkout(IPaymentGateway gateway)
{
    public Task<string> PayAsync(decimal amount, CancellationToken cancellationToken)
    {
        ArgumentOutOfRangeException.ThrowIfNegativeOrZero(amount);
        return gateway.ChargeAsync(amount, cancellationToken);
    }
}

