public sealed class Expense(decimal amount)
{
    public bool Approved { get; private set; }
    public void Approve(decimal approvalLimit)
    {
        if (amount > approvalLimit)
            throw new InvalidOperationException("Approval limit exceeded.");
        Approved = true;
    }
}

