public interface IExpenseStore
{
    Task<Expense?> FindAsync(Guid id, CancellationToken cancellationToken);
    Task SaveAsync(CancellationToken cancellationToken);
}

public sealed class ApproveExpense(IExpenseStore store)
{
    public async Task ExecuteAsync(Guid id, decimal limit, CancellationToken cancellationToken)
    {
        var expense = await store.FindAsync(id, cancellationToken)
            ?? throw new KeyNotFoundException("Expense not found.");
        expense.Approve(limit);
        await store.SaveAsync(cancellationToken);
    }
}

using System.Text.Json;

public static async Task PlaceAsync(
    OrdersDbContext database, Order order, CancellationToken cancellationToken)
{
    var message = new OrderPlaced(Guid.NewGuid(), order.Id, order.Total);
    database.Orders.Add(order);
    database.Outbox.Add(new OutboxMessage(
        message.MessageId, nameof(OrderPlaced),
        JsonSerializer.Serialize(message), DateTime.UtcNow));

    await database.SaveChangesAsync(cancellationToken);
}
